@startuml

class RepairShop {
  + name : string
  + address : string
  + numberOfEmployees : int
}

class Employee {
  + taxCode : string
  + address : string
  + phoneNumber : string
  + yearsOfService : int
}

class Director extends Employee {
  + age : int
}

class Owner {
  + taxCode : string
  + address : string
  + phoneNumber : string
}

class Vehicle {
  + model : string
  + type : string
  + licensePlate : string
  + registrationYear : int
}

class Repair {
  + code : string
  + checkInTime : datetime
  + checkInDate : date
  + returnTime : time
  + returnDate : date
}

RepairShop "1" -- "*" Employee : has
RepairShop "1" -- "1" Director : has director
RepairShop "1" -- "*" Repair : performs
RepairShop "1" -- "*" Repair : manages
Vehicle "1" -- "1" Owner : belongs to
Vehicle "1" -- "*" Repair : is subject of
Vehicle "1" -- "1" Owner : owned by

@enduml

